SELECT length('42'), upper('42'), lower('42'), substr('42', -3, 0), instr('42', 'señor'), replace('42', 'é', ''), trim('42'), ltrim('42', 'ab'), hex('42'), quote('42'), unicode('42'), '42' LIKE '_', '42' GLOB '*[a-m]*', char(89, 464), '42' || 'señor', '42' < 'señor', '42' = 'señor' COLLATE NOCASE;
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', 4, 3), instr('tau', '-7'), replace('tau', 'e', '_'), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE '_', 'tau' GLOB 'a*', char(83, 768), 'tau' || '-7', 'tau' < '-7', 'tau' = '-7' COLLATE NOCASE;
