CREATE UNIQUE INDEX IF NOT EXISTS i40 ON t1(id DESC, id);
SELECT id, id FROM t1 WHERE id IS NOT NULL ORDER BY id, id;
SELECT count(*) FROM t1 INDEXED BY i40 WHERE id IS NOT NULL;
REINDEX t1;
DROP INDEX IF EXISTS i40;
